#!/usr/bin/env bash
# OWNER-ONLY — destructive. Purge Newsfind topic test-run data on VPS slots.
#
# DELETES (data generated by test runs only):
#   DB    topics, topic_events, topic_subscriptions, topic_refresh_deltas, topic_webhooks
#   disk  <slot state dir>/news/*
#
# NEVER TOUCHES (product know-how):
#   documents, events, signals            RAG corpus + embeddings
#   users, user_profiles                  accounts
#   reports, alerts                       signal_gather
#   agent_sessions, agent_events          replay history
#   alembic_version                       schema state
#   local_knowledge_sources/, artifacts/, S3/MinIO, claude_home/
#
# Protected table row counts are captured before and after the purge and must
# match exactly; any drift aborts with a non-zero exit.
#
# Usage:
#   scripts/owner/purge_test_topic_data.sh --slot test1          # dry run (default)
#   scripts/owner/purge_test_topic_data.sh --slot test1 --yes    # execute
#   scripts/owner/purge_test_topic_data.sh --slot all --yes
#
# Run only on machines that held test traffic. Never with customer data present.
set -euo pipefail

SSH_KEY="${SSH_KEY:-$HOME/.ssh/contabo_ed25519}"
VPS_HOST="${VPS_HOST:-root@79.143.179.212}"
REMOTE_SCRIPT="$(cd "$(dirname "$0")" && pwd)/_purge_remote.sh"

PURGE_TABLES="topic_refresh_deltas topic_webhooks topic_subscriptions topic_events topics"
PROTECTED_TABLES="documents events signals users user_profiles reports alerts agent_sessions agent_events alembic_version"

SLOT=""
APPLY="no"

usage() {
  sed -n '2,24p' "$0" | sed 's/^# \{0,1\}//'
  exit "${1:-1}"
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --slot) SLOT="${2:?--slot needs a value}"; shift 2 ;;
    --yes) APPLY="yes"; shift ;;
    -h|--help) usage 0 ;;
    *) echo "Unknown argument: $1" >&2; usage ;;
  esac
done

case "$SLOT" in
  prod|test1|test2) SLOTS="$SLOT" ;;
  all) SLOTS="prod test1 test2" ;;
  "") echo "Missing --slot (prod|test1|test2|all)" >&2; usage ;;
  *) echo "Unknown slot: $SLOT" >&2; usage ;;
esac

slot_target() {
  case "$1" in
    prod)  echo "agent_bench-postgres-1 agentic       agent_bench/state" ;;
    test1) echo "test1-postgres-1       agentic_test1 agent_bench_test1/state_test1" ;;
    test2) echo "test2-postgres-1       agentic_test2 agent_bench_test2/state_test2" ;;
  esac
}

if [[ "$APPLY" == "yes" ]]; then
  echo "!! DESTRUCTIVE: purging topic test data on slot(s): $SLOTS"
  read -r -p "Type PURGE to continue: " confirm
  [[ "$confirm" == "PURGE" ]] || { echo "Aborted."; exit 1; }
fi

REMOTE_PATH="/tmp/newsfind_purge_$$.sh"
scp -q -i "$SSH_KEY" "$REMOTE_SCRIPT" "$VPS_HOST:$REMOTE_PATH"
trap 'ssh -i "$SSH_KEY" "$VPS_HOST" "rm -f $REMOTE_PATH" >/dev/null 2>&1 || true' EXIT

for slot in $SLOTS; do
  read -r container db state_rel <<<"$(slot_target "$slot")"
  echo
  echo "================ $slot ($db) ================"
  ssh -n -i "$SSH_KEY" "$VPS_HOST" \
    "bash $REMOTE_PATH '$container' '$db' '$state_rel' '$APPLY' '$PURGE_TABLES' '$PROTECTED_TABLES'"
done

echo
if [[ "$APPLY" == "yes" ]]; then
  echo "Done. Topic test data purged; product know-how untouched."
else
  echo "Dry run complete. Add --yes to execute."
fi
